local GunpowderMill = {}
local PRODUCTS = {
    serpentine_powder = { name = "Serpentin smodek", saltpeterCost = 2, sulfurCost = 1, charcoalCost = 1, time = 2, cost = 25, potency = 30, description = "Preprost praškasti serpentin smodek." },
    corned_powder = { name = "Zrnati smodek", saltpeterCost = 3, sulfurCost = 1, charcoalCost = 1, time = 4, cost = 65, potency = 50, prestige = 1, description = "Zrnati smodek z boljšim zgorevanjem." },
    fine_milled_powder = { name = "Fino mlet smodek", saltpeterCost = 3, sulfurCost = 2, charcoalCost = 2, time = 6, cost = 150, potency = 70, prestige = 3, happiness = 1, description = "Fino mlet smodek za topove." },
    military_grade_powder = { name = "Vojaški smodek", saltpeterCost = 4, sulfurCost = 2, charcoalCost = 2, time = 8, cost = 320, potency = 90, prestige = 6, happiness = 2, description = "Vojaški smodek za oblegovalne naprave." },
    refined_powder = { name = "Rafiniran smodek", saltpeterCost = 4, sulfurCost = 2, charcoalCost = 2, silverCost = 1, time = 11, cost = 700, potency = 110, prestige = 12, happiness = 3, description = "Rafiniran smodek s srebrovo korekcijo." },
    royal_grand_powder = { name = "Kraljevski veliki smodek", saltpeterCost = 6, sulfurCost = 3, charcoalCost = 3, goldCost = 1, silverCost = 1, jewelCost = 1, time = 16, cost = 1700, potency = 150, prestige = 38, happiness = 8, description = "Veliki kraljevski smodek z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Smodniška delavnica", cost = { gold = 350, wood = 150, stone = 200 }, upkeep = 9, qualityBonus = 5 },
    stamping_mill = { name = "Mlinski mlin", cost = { gold = 1200, wood = 350, stone = 500, iron = 10 }, upkeep = 28, qualityBonus = 18 },
    corning_room = { name = "Zrnica", cost = { gold = 2800, wood = 500, stone = 800, silver = 40, saltpeter = 10 }, upkeep = 65, qualityBonus = 30 },
    royal_powder_atelier = { name = "Kraljevski atelje smodnika", cost = { gold = 11000, wood = 800, stone = 1500, gold = 100, jewel = 25 }, upkeep = 220, qualityBonus = 55, prestigeBonus = 45 },
}
GunpowderMill.saltpeterStock = 16; GunpowderMill.sulfurStock = 12; GunpowderMill.charcoalStock = 14; GunpowderMill.silverStock = 8; GunpowderMill.goldStock = 6; GunpowderMill.jewelStock = 6
GunpowderMill.productStock = {}; GunpowderMill.buildings = {}; GunpowderMill.maker = nil; GunpowderMill.activeMaking = {}; GunpowderMill.totalProducts = 0; GunpowderMill.dayTimer = 0
function GunpowderMill.init() GunpowderMill.saltpeterStock=16; GunpowderMill.sulfurStock=12; GunpowderMill.charcoalStock=14; GunpowderMill.silverStock=8; GunpowderMill.goldStock=6; GunpowderMill.jewelStock=6; GunpowderMill.productStock={}; GunpowderMill.buildings={}; GunpowderMill.maker=nil; GunpowderMill.activeMaking={}; GunpowderMill.totalProducts=0; GunpowderMill.dayTimer=0; print("[GunpowderMill] Royal Gunpowder Mill System initialized (6 products, 4 buildings)") end
function GunpowderMill.hireMaker(n,s) s=s or math.random(50,90); local c=550+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GunpowderMill.maker={name=n or ("Smodnikar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Smodnikar najet: %s (spretnost: %d)",GunpowderMill.maker.name,s),"success") end; return true end
function GunpowderMill.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GunpowderMill.build(id) local ok,e=GunpowderMill.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GunpowderMill.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GunpowderMill.getQualityBonus() local b=0; for _,bd in ipairs(GunpowderMill.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GunpowderMill.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.saltpeterCost and GunpowderMill.saltpeterStock<(d.saltpeterCost or 0) then return false,"Premalo salitre" end; if d.sulfurCost and GunpowderMill.sulfurStock<(d.sulfurCost or 0) then return false,"Premalo žvepla" end; if d.charcoalCost and GunpowderMill.charcoalStock<(d.charcoalCost or 0) then return false,"Premalo oglja" end; if d.silverCost and GunpowderMill.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GunpowderMill.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GunpowderMill.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if #GunpowderMill.buildings==0 then return false,"Potrebna delavnica" end; if not GunpowderMill.maker then return false,"Potreben smodnikar" end; return true end
function GunpowderMill.make(pt,qty) qty=qty or 5; local ok,e=GunpowderMill.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.saltpeterCost then GunpowderMill.saltpeterStock=GunpowderMill.saltpeterStock-d.saltpeterCost*qty end; if d.sulfurCost then GunpowderMill.sulfurStock=GunpowderMill.sulfurStock-d.sulfurCost*qty end; if d.charcoalCost then GunpowderMill.charcoalStock=GunpowderMill.charcoalStock-d.charcoalCost*qty end; if d.silverCost then GunpowderMill.silverStock=GunpowderMill.silverStock-d.silverCost*qty end; if d.goldCost then GunpowderMill.goldStock=GunpowderMill.goldStock-d.goldCost*qty end; if d.jewelCost then GunpowderMill.jewelStock=GunpowderMill.jewelStock-d.jewelCost*qty end; local t=d.time; if GunpowderMill.maker then t=math.max(1,t-math.floor(GunpowderMill.maker.skill/12)) end; table.insert(GunpowderMill.activeMaking,{id="powder_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,potency=d.potency or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GunpowderMill.completeMaking(m) local q=1.0+(GunpowderMill.getQualityBonus()/100); if GunpowderMill.maker then q=q+(GunpowderMill.maker.skill/180) end; q=math.min(2.0,q); GunpowderMill.productStock[m.productType]=(GunpowderMill.productStock[m.productType] or 0)+m.quantity; GunpowderMill.totalProducts=GunpowderMill.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GunpowderMill.maker then GunpowderMill.maker.itemsMade=GunpowderMill.maker.itemsMade+m.quantity; if math.random()<0.20 then GunpowderMill.maker.skill=math.min(100,GunpowderMill.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Smodek izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"gunpowder.completed",{productName=m.productName,potency=m.potency}) end end
function GunpowderMill.update(dt) if not _G.state then return end; GunpowderMill.dayTimer=GunpowderMill.dayTimer+dt; if GunpowderMill.dayTimer>=30 then GunpowderMill.dayTimer=0; for i=#GunpowderMill.activeMaking,1,-1 do local m=GunpowderMill.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GunpowderMill.completeMaking(m); table.remove(GunpowderMill.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GunpowderMill.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GunpowderMill.maker then tu=tu+18 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GunpowderMill.getStats() return {saltpeterStock=GunpowderMill.saltpeterStock,sulfurStock=GunpowderMill.sulfurStock,charcoalStock=GunpowderMill.charcoalStock,silverStock=GunpowderMill.silverStock,goldStock=GunpowderMill.goldStock,jewelStock=GunpowderMill.jewelStock,productStock=GunpowderMill.productStock,numBuildings=#GunpowderMill.buildings,hasMaker=GunpowderMill.maker~=nil,makerName=GunpowderMill.maker and GunpowderMill.maker.name or "—",makerSkill=GunpowderMill.maker and GunpowderMill.maker.skill or 0,activeMaking=#GunpowderMill.activeMaking,totalProducts=GunpowderMill.totalProducts} end
return GunpowderMill
